 30	func execProviderBackups() {
 31		failed := runProviderBackups()
 32	
 33		// If running one-shot (no scheduler) and any provider failed, surface a
 34		// non-zero exit. With a scheduler the next-run banner is enough.
 35		if job == nil && failed > 0 {
