148	// cleanupWorkingDir removes the working directory after a backup run.
149	// It refuses to remove anything that does not resolve to a path inside
150	// backupDir to protect against a misconfigured GIT_WORKING_DIR wiping
151	// arbitrary filesystem locations.
152	func cleanupWorkingDir(workingDir, backupDir string) {
153		logger.Println("cleaning up")
154	
155		if workingDir == "" {
156			return
157		}
158	
159		absWorking, err := filepath.Abs(filepath.Clean(workingDir))
160		if err != nil {
161			logger.Printf("failed to resolve working directory %q: %v", workingDir, err)
162	
163			return
164		}
165	
166		absBackup, err := filepath.Abs(filepath.Clean(backupDir))
167		if err != nil {
168			logger.Printf("failed to resolve backup directory %q: %v", backupDir, err)
169	
170			return
171		}
172	
173		if absWorking == absBackup {
174			logger.Printf("refusing to clean working directory %q: equals backup directory", absWorking)
175	
176			return
177		}
178	
179		if !strings.HasPrefix(absWorking+string(os.PathSeparator), absBackup+string(os.PathSeparator)) {
180			logger.Printf("refusing to clean working directory %q: not inside backup directory %q", absWorking, absBackup)
181	
182			return
183		}
184	
185		if err := os.RemoveAll(absWorking); err != nil {
186			logger.Printf("failed to clean working directory %q: %v", absWorking, err)
187		}
188	}
