523	// runScheduledJob registers the backup task with the scheduler, starts it and
524	// blocks until shutdown.
525	func runScheduledJob(s gocron.Scheduler, definition gocron.JobDefinition, options ...gocron.JobOption) error {
526		var err error
527	
528		job, err = s.NewJob(
529			definition,
530			gocron.NewTask(execProviderBackups),
531			options...,
532		)
533		if err != nil {
534			return errors.Wrap(err, "failed to create job")
535		}
536	
537		s.Start()
538		waitForShutdown(s)
539	
540		return nil
541	}
