543	// waitForShutdown blocks until SIGINT or SIGTERM is received and then
544	// shuts the scheduler down gracefully so any running job finishes (and
545	// its deferred cleanup runs) before the process exits.
546	func waitForShutdown(s gocron.Scheduler) {
547		sigCh := make(chan os.Signal, 1)
548		signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
549	
550		sig := <-sigCh
551		logger.Printf("received %s; shutting down scheduler", sig)
552	
553		if err := s.Shutdown(); err != nil {
554			logger.Printf("scheduler shutdown error: %v", err)
555		}
556	}
