LABEL maintainer="Jon Hadfield jon@lessknown.co.uk"

RUN addgroup -S nonroot \
    && adduser -S nonroot -G nonroot \
    && apk add --update --no-cache bash ca-certificates curl git git-lfs grep jq \
    && rm -f "/var/cache/apk/*"

ARG TAG

WORKDIR /tmp
