    && tar -xvzf soba.tar.gz \
    && rm ./*.gz \
    && mv ./soba /soba \
    && rm -rf /tmp/* \
    && chmod 755 /soba

USER nonroot

ENTRYPOINT ["/bin/bash", "-c", "/soba \"$@\"", "--"]
